 public static void aim(){try{keepPerspective();if(rightAim&&(R.get(mc(),"screen")!=null||!active()))setAim(false);Object mc=mc(),player=R.get(mc,"player");if(!active()||player==null||R.get(mc,"screen")!=null||!gun(player)){aimed=false;return;}Object hit=R.get(mod(),"crosshairTarget");if(hit==null)return;Object target=R.call(hit,"getLocation"),eye=R.call(player,"getEyePosition");double dx=v(target,"x")-v(eye,"x"),dy=v(target,"y")-v(eye,"y"),dz=v(target,"z")-v(eye,"z");if(dx*dx+dy*dy+dz*dz<.04)return;double[] a=Rules.angles(dx,dy,dz);double yaw=a[0],pitch=a[1];if(aimed&&aimPlayer==player){yaw=R.num(R.call(player,"getYRot"))+Rules.wrap(yaw-lastDesiredYaw);pitch=R.num(R.call(player,"getXRot"))+(pitch-lastDesiredPitch);}R.set(mod(),"livingPitch",(float)R.num(R.call(player,"getXRot")));R.set(mod(),"livingYaw",(float)R.num(R.call(player,"getYRot")));R.set(mod(),"livingHeadYaw",(float)R.num(R.call(player,"getYHeadRot")));R.set(mod(),"livingBodyYaw",(float)R.num(R.get(player,"yBodyRot")));lastDesiredYaw=a[0];lastDesiredPitch=a[1];aimed=true;aimPlayer=player;R.call(player,"setYRot",(float)yaw);R.call(player,"setYHeadRot",(float)yaw);R.set(player,"yBodyRot",(float)yaw);R.call(player,"setXRot",(float)Math.max(-89.9,Math.min(89.9,pitch)));}catch(Throwable e){warn("gun aim",e);}}
 public static void selectBreakTarget(){try{Object mc=mc(),player=R.get(mc,"player");if(!active()||player==null||R.get(mc,"screen")!=null||gun(player))return;Object[] ray=CursorTarget.ray(mc);Object hit=CursorTarget.pickRay(mc,ray[0],ray[1],true);if(hit!=null){R.set(mc,"hitResult",hit);R.set(mc,"crosshairPickEntity",R.call(hit,"getType").toString().equals("ENTITY")?R.call(hit,"getEntity"):null);}}catch(Throwable e){warn("cursor block breaking",e);}}
 public static void hideUnseen(Object entity,Object callback){try{Object mc=mc(),player=R.get(mc,"player");if(!active()||player==null||entity==player)return;Object eye=R.call(player,"getEyePosition"),point=R.call(entity,"getBoundingBox");point=R.call(point,"getCenter");double dx=v(point,"x")-v(eye,"x"),dz=v(point,"z")-v(eye,"z");Object camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera");if(!Rules.inView(dx,dz,R.num(R.call(camera,"getYRot")))){R.call(callback,"cancel");return;}Object level=R.get(mc,"level"),head=R.call(entity,"getEyePosition"),feet=plus(R.call(entity,"position"),0,.25,0);if(!visiblePoint(level,player,eye,head)&&!visiblePoint(level,player,eye,point)&&!visiblePoint(level,player,eye,feet))R.call(callback,"cancel");}catch(Throwable e){warn("isometric field of vision",e);}}
 static boolean visiblePoint(Object level,Object player,Object eye,Object point){Object obstruction=clip(level,player,eye,point);return !R.call(obstruction,"getType").toString().equals("BLOCK")||distance(eye,R.call(obstruction,"getLocation"))>=distance(eye,point)-.1;}
 public static void fog(Object graphics){Fog.render(graphics);}
 public static void cancelScope(Object callback){try{if(active())R.call(callback,"cancel");}catch(Throwable e){warn("scope FOV",e);}}
