 static void open(Object mc,Object hit){Object player=R.get(mc,"player"),game=R.get(mc,"gameMode"),hand=R.get(R.type("net.minecraft.world.InteractionHand"),"MAIN_HAND");R.set(mc,"hitResult",hit);R.set(mc,"crosshairPickEntity",R.call(hit,"getType").toString().equals("ENTITY")?R.call(hit,"getEntity"):null);Object result=R.call(hit,"getType").toString().equals("BLOCK")?R.call(game,"useItemOn",player,hand,hit):R.call(game,"interact",player,R.call(hit,"getEntity"),hand);if(R.yes(R.call(result,"shouldSwing")))R.call(player,"swing",hand);}
