 static void keepPerspective(){if(!active()||R.get(mc(),"player")==null||!gun(R.get(mc(),"player")))return;Object options=R.get(mc(),"options"),type=R.get(R.type("net.minecraft.client.CameraType"),"THIRD_PERSON_BACK");if(R.call(options,"getCameraType")!=type)R.call(options,"setCameraType",type);}
